function fold_left(op, initial, sequence) {
    function iter(result, rest) {
        return is_null(rest)
               ? result
               : iter(op(result, head(rest)),
                      tail(rest));
    }
    return iter(initial, sequence);
}

function divide(x, y) {
    return x / y;
}

function reverse(sequence) {
    return fold_right((x, y) => ??, null, sequence);
}

